INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, "クローチェ", "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", 1, 10001, -470.0, 2, 2002, 126401, "2023/09/22 14:59:59", 0.0, 1.47, 1, "2023/06/30 12:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, "クローチェ", "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", 2, 10002, -470.0, 1, 2002, 126401, "2023/09/22 14:59:59", 0.0, 2.15, 2, "2023/06/30 12:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, "ライラエル", "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 1, 10003, -470.0, 2, 2002, 126501, "2023/09/22 14:59:59", 0.0, 0.0, 2, "2023/06/30 12:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, "ライラエル", "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 2, 10004, -470.0, 1, 2002, 126501, "2023/09/22 14:59:59", 0.0, 0.0, 1, "2023/06/30 12:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, "リンド", "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 1, 10005, -470.0, 2, 2002, 127702, "2023/12/22 14:59:59", 0.0, 0.0, 2, "2023/09/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, "リンド", "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 2, 10006, -470.0, 2, 2002, 127702, "2023/12/22 14:59:59", 0.0, 0.0, 2, "2023/09/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, "ヴルム", "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 1, 10007, -470.0, 1, 2002, 127802, "2023/12/22 14:59:59", 0.0, 0.0, 1, "2023/09/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, "ヴルム", "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 2, 10008, -470.0, 1, 2002, 127802, "2023/12/22 14:59:59", 0.0, 6.5, 2, "2023/09/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, "アネモネ", "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 1, 10009, -470.0, 1, 2002, 129602, "2024/03/22 14:59:59", 0.0, 0.0, 2, "2023/12/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, "アネモネ", "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 2, 10010, -470.0, 1, 2002, 129602, "2024/03/22 14:59:59", 0.0, 0.0, 2, "2023/12/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, "ネフィ=ネラ", "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 1, 10011, -470.0, 1, 2002, 129701, "2024/03/22 14:59:59", 0.0, 0.0, 1, "2023/12/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, "ネフィ=ネラ", "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 2, 10012, -470.0, 1, 2002, 129701, "2024/03/22 14:59:59", 0.0, 6.2, 2, "2023/12/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, "カノン", "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 1, 10013, -470.0, 5, 2002, 130301, "2024/06/22 14:59:59", 0.0, 3.1, 3, "2024/03/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, "カノン", "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 2, 10014, -470.0, 2, 2002, 130301, "2024/06/22 14:59:59", 0.0, 6.15, 3, "2024/03/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, "ナーナ", "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 1, 10015, -470.0, 2, 2002, 130401, "2024/06/22 14:59:59", 0.0, 0.0, 2, "2024/03/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, "ナーナ", "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 2, 10016, -470.0, 1, 2002, 130401, "2024/06/22 14:59:59", 0.0, 3.35, 2, "2024/03/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, "ホウオウ", "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 1, 10017, -470.0, 1, 2002, 130502, "2024/09/22 14:59:59", 0.0, 0.0, 1, "2024/06/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, "ホウオウ", "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 2, 10018, -470.0, 1, 2002, 130502, "2024/09/22 14:59:59", 0.0, 3.18, 2, "2024/06/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, "ホウオウ", "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 3, 10019, -470.0, 4, 2002, 130503, "2024/09/22 14:59:59", 0.0, 0.0, 4, "2024/06/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, "ネア", "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 1, 10020, -470.0, 2, 2002, 123301, "2024/09/22 14:59:59", 0.0, 4.9, 1, "2024/06/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, "ネア", "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 2, 10021, -470.0, 2, 2002, 123301, "2024/09/22 14:59:59", 0.0, 4.8, 1, "2024/06/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, "カリザ", "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 1, 10022, -470.0, 1, 2002, 133301, "2024/12/22 14:59:59", 0.0, 4.922, 3, "2024/09/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, "カリザ", "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 2, 10023, -470.0, 5, 2002, 133301, "2024/12/22 14:59:59", 0.0, 9.638, 3, "2024/09/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, "ミーア", "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 1, 10024, -470.0, 2, 2002, 133401, "2024/12/22 14:59:59", 0.0, 2.88, 1, "2024/09/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, "ミーア", "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 2, 10025, -470.0, 1, 2002, 133401, "2024/12/22 14:59:59", 0.0, 4.818, 5, "2024/09/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, "グレイス", "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 1, 10026, -470.0, 1, 2002, 133002, "2025/03/22 14:59:59", 0.0, 1.78, 2, "2024/12/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, "グレイス", "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 2, 10027, -470.0, 7, 2002, 133002, "2025/03/22 14:59:59", 0.0, 6.15, 1, "2024/12/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, "ヴァイオレット", "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 1, 10028, -470.0, 2, 2002, 133102, "2025/03/22 14:59:59", 0.0, 4.28, 6, "2024/12/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, "ヴァイオレット", "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 2, 10029, -470.0, 1, 2002, 133102, "2025/03/22 14:59:59", 0.0, 0.0, 1, "2024/12/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, "ルルィ", "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 1, 10030, -470.0, 1, 2002, 136902, "2025/06/23 14:59:59", 0.0, 5.53, 2, "2025/03/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, "ルルィ", "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 2, 10031, -470.0, 7, 2002, 136902, "2025/06/23 14:59:59", 0.0, 6.05, 9, "2025/03/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, "デュラン", "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 1, 10032, -470.0, 1, 2002, 137001, "2025/06/23 14:59:59", 0.0, 0.0, 2, "2025/03/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, "デュラン", "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 2, 10033, -470.0, 1, 2002, 137001, "2025/06/23 14:59:59", 0.0, 0.0, 2, "2025/03/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, "サツキ", "おう\n好きなもん持ってきな", 1, 10034, -470.0, 2, 2002, 135902, "2025/09/23 14:59:59", 0.0, 0.0, 2, "2025/06/16 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, "サツキ", "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 2, 10035, -470.0, 6, 2002, 135902, "2025/09/23 14:59:59", 0.0, 4.935, 1, "2025/06/16 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, "ユキノ", "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 1, 10036, -470.0, 5, 2002, 135802, "2025/09/23 14:59:59", 0.0, 7.441, 2, "2025/06/16 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, "ユキノ", "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 2, 10037, -470.0, 7, 2002, 135802, "2025/09/23 14:59:59", 0.0, 0.0, 7, "2025/06/16 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, "クルル", "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 1, 10038, -470.0, 2, 2002, 130901, "2025/12/22 14:59:59", 0.0, 2.295, 2, "2025/09/16 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, "クルル", "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 2, 10039, -470.0, 6, 2002, 130901, "2025/12/22 14:59:59", 0.0, 6.281, 1, "2025/09/16 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, "ヴォルガーノ", "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 1, 10040, -470.0, 1, 2002, 137701, "2025/12/22 14:59:59", 0.0, 5.549, 2, "2025/09/16 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, "ヴォルガーノ", "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 2, 10041, -470.0, 6, 2002, 137701, "2025/12/22 14:59:59", 0.0, 2.64, 3, "2025/09/16 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, "ライラエル", "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 1, 10042, -470.0, 4, 2002, 132801, "2026/03/23 11:59:59", 0.0, 7.642, 7, "2025/12/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, "ライラエル", "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 2, 10043, -470.0, 1, 2002, 132802, "2026/03/23 11:59:59", 0.0, 0.0, 1, "2025/12/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, "クローチェ", "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 1, 10044, -470.0, 1, 2002, 134502, "2026/03/23 11:59:59", 0.0, 0.0, 1, "2025/12/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, "クローチェ", "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 2, 10045, -470.0, 1, 2002, 134501, "2026/03/23 11:59:59", 0.0, 3.72, 2, "2025/12/15 15:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, "ネフィ＝ネラ", "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 1, 10046, -470.0, 1, 2002, 138201, "2026/06/22 11:59:59", 0.0, 4.991, 2, "2026/03/16 12:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, "ネフィ＝ネラ", "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 2, 10047, -470.0, 4, 2002, 138201, "2026/06/22 11:59:59", 0.0, 3.877, 1, "2026/03/16 12:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, "アラクネ", "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 1, 10048, -470.0, 6, 2002, 136001, "2026/06/22 11:59:59", 0.0, 1.71, 4, "2026/03/16 12:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, "アラクネ", "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 2, 10049, -470.0, 2, 2002, 136001, "2026/06/22 11:59:59", 0.0, 5.32, 5, "2026/03/16 12:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (13, "アネモネ", "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 1, 10050, -470.0, 4, 2002, 135401, "2026/09/22 11:59:59", 0.0, 3.727, 9, "2026/06/15 12:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (13, "アネモネ", "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 2, 10051, -470.0, 9, 2002, 135401, "2026/09/22 11:59:59", 0.0, 7.213, 7, "2026/06/15 12:00:00");
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (13, "クリア", "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 1, 10052, -470.0, 2, 2002, 135301, "2026/09/22 11:59:59", 0.0, 1.874, 1, "2026/06/15 12:00:00");
